示例：该组件实现了一个带有自定义分割线样式的选择器（Select）。布局宽度占据整个屏幕，高度由内容决定。组件的垂直方向上包含一个选择器，选择器的选项以垂直布局方式排列，每个选项之间通过自定义的分割线进行分隔。
选择器的样式包括字体大小、字体颜色、选中项和未选中项的字体样式、箭头位置、菜单对齐方式、选项的宽度和高度等属性。选择器的功能包括点击事件和状态效果，用户可以通过点击选择器触发相应操作，选择器也可以在选中或未选中状态下进行展示。
整个布局通过 Column 布局保证选择器在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct SelectExample {
  @State text: string = "TTTTT" // 当前选中的文本
  @State index: number = -1 // 当前选中的索引，初始值为-1表示未选中
  @State arrowPosition: ArrowPosition = ArrowPosition.END // 箭头位置，初始值为END

  build() {
    Column() {
      Select([
        { value: 'aaa', icon: $r("app.media.icon") }, // 选项1，包含文本和图标
        { value: 'bbb', icon: $r("app.media.icon") }, // 选项2，包含文本和图标
        { value: 'ccc', icon: $r("app.media.icon") }, // 选项3，包含文本和图标
        { value: 'ddd', icon: $r("app.media.icon") }  // 选项4，包含文本和图标
      ])
      .selected(this.index) // 设置当前选中的索引
      .value(this.text) // 设置当前选中的文本
      .font({ size: 16, weight: 500 }) // 设置字体大小和粗细
      .fontColor('#182431') // 设置字体颜色
      .selectedOptionFont({ size: 16, weight: 400 }) // 设置选中项的字体样式
      .optionFont({ size: 16, weight: 400 }) // 设置未选中项的字体样式
      .arrowPosition(this.arrowPosition) // 设置箭头位置
      .menuAlign(MenuAlignType.START, {dx:0, dy:0}) // 设置菜单对齐方式
      .optionWidth(200) // 设置选项的宽度
      .optionHeight(300) // 设置选项的高度
      .divider({ strokeWidth: 5, color: Color.Blue, startMargin: 10, endMargin: 10 }) // 设置分割线的样式
      .onSelect((index: number, text?: string | undefined) => { // 选择事件处理函数
        console.info('Select:' + index) // 打印选中的索引
        this.index = index; // 更新当前选中的索引
        if (text) {
          this.text = text; // 更新当前选中的文本
        }
      })
    }.width('100%') // 设置布局宽度为100%
  }
}

示例：该组件实现了一个下拉菜单中图片为Symbol的Select组件。布局宽度占据整个屏幕，高度根据内容自适应。组件的垂直方向上包含一个Select组件，Select组件的选项以水平布局方式排列，每个选项包含一个Symbol图标和一个文本值。
Select组件的样式包括字体大小、字体颜色、选中项和未选中项的字体样式、选项之间的间距、箭头位置等属性。Select组件的功能包括选项的选择事件，用户可以通过点击选项触发相应操作，并更新当前选中的索引和文本值。
整个布局通过Column布局保证Select组件在垂直方向上有序排列，确保界面整洁美观。
// 导入SymbolGlyphModifier模块，用于创建Symbol图标的样式
import { SymbolGlyphModifier } from '@kit.ArkUI'

// 定义一个名为SelectExample的组件，作为页面的入口组件
@Entry
@Component
struct SelectExample {
  // 定义一个状态变量text，用于存储当前选中的文本值，初始值为"TTTTT"
  @State text: string = "TTTTT"

  // 定义一个状态变量index，用于存储当前选中的索引，初始值为2
  @State index: number = 2

  // 定义一个状态变量space，用于设置选项之间的间距，初始值为8
  @State space: number = 8

  // 定义一个状态变量arrowPosition，用于设置箭头的位置，初始值为ArrowPosition.END
  @State arrowPosition: ArrowPosition = ArrowPosition.END

  // 定义一个状态变量symbolModifier1，用于创建第一个Symbol图标的样式，图标为系统图标ohos_wifi，颜色为绿色
  @State symbolModifier1: SymbolGlyphModifier = new SymbolGlyphModifier($r('sys.symbol.ohos_wifi')).fontColor([Color.Green]);

  // 定义一个状态变量symbolModifier2，用于创建第二个Symbol图标的样式，图标为系统图标ohos_star，颜色为红色
  @State symbolModifier2: SymbolGlyphModifier = new SymbolGlyphModifier($r('sys.symbol.ohos_star')).fontColor([Color.Red]);

  // 定义一个状态变量symbolModifier3，用于创建第三个Symbol图标的样式，图标为系统图标ohos_trash，颜色为灰色
  @State symbolModifier3: SymbolGlyphModifier = new SymbolGlyphModifier($r('sys.symbol.ohos_trash')).fontColor([Color.Gray]);

  // 定义一个状态变量symbolModifier4，用于创建第四个Symbol图标的样式，图标为系统图标exposure，颜色为灰色
  @State symbolModifier4: SymbolGlyphModifier = new SymbolGlyphModifier($r('sys.symbol.exposure')).fontColor([Color.Gray]);

  // 构建组件的UI结构
  build() {
    // 使用Column布局，宽度占据整个屏幕
    Column() {
      // 创建一个Select组件，选项数组包含四个选项，每个选项包含一个文本值和一个Symbol图标
      Select([
        { value: 'aaa', symbolIcon: this.symbolModifier1 },
        { value: 'bbb', symbolIcon: this.symbolModifier2 },
        { value: 'ccc', symbolIcon: this.symbolModifier3 },
        { value: 'ddd', symbolIcon: this.symbolModifier4 }
      ])
      // 设置当前选中的索引
      .selected(this.index)
      // 设置当前选中的文本值
      .value(this.text)
      // 设置Select组件的字体样式，字体大小为16，字体粗细为500
      .font({ size: 16, weight: 500 })
      // 设置Select组件的字体颜色为#182431
      .fontColor('#182431')
      // 设置选中项的字体样式，字体大小为16，字体粗细为400
      .selectedOptionFont({ size: 16, weight: 400 })
      // 设置未选中项的字体样式，字体大小为16，字体粗细为400
      .optionFont({ size: 16, weight: 400 })
      // 设置选项之间的间距
      .space(this.space)
      // 设置箭头的位置
      .arrowPosition(this.arrowPosition)
      // 设置菜单的对齐方式为START，偏移量为{dx:0, dy:0}
      .menuAlign(MenuAlignType.START, {dx:0, dy:0})
      // 设置选项选择事件的回调函数
      .onSelect((index:number, text?: string | undefined)=>{
        // 打印当前选中的索引
        console.info('Select:' + index)
        // 更新当前选中的索引
        this.index = index;
        // 如果传入了文本值，则更新当前选中的文本值
        if(text){
          this.text = text;
        }
      })
    }
    // 设置Column布局的宽度为100%
    .width('100%')
  }
}

示例：该示例实现了一个自定义下拉菜单选项的Select组件。布局上，Select组件位于一个Column容器内，该容器包含一个Row组件，Row组件中嵌套了Select组件。Select组件的布局宽度占据整个屏幕，高度设为50%，内边距为左右35vp、顶部35vp。Select组件的垂直方向上被分为多个部分，每个部分包含一个标题和一组按钮。每个按钮组的按钮以水平布局方式排列，按钮之间的间距均匀分布，且对齐方式为居中对齐。

Select组件的样式包括背景颜色、边框圆角（或半径）、宽度和高度等属性，支持不同的样式展示。Select组件的功能包括点击事件和状态效果，用户可以通过点击Select组件触发相应操作，Select组件也可以在启用或禁用状态下进行展示。

整个布局通过Flex布局保证按钮在垂直方向上有序排列，确保界面整洁美观。
import { MenuItemModifier, SymbolGlyphModifier } from '@kit.ArkUI'

// 定义一个自定义的MenuItem内容修饰器类
class MyMenuItemContentModifier implements ContentModifier<MenuItemConfiguration> {
  modifierText: string = ""
  constructor(text: string) {
    this.modifierText = text;
  }
  // 应用内容修饰器，返回一个MenuItemBuilder的包装构建器
  applyContent(): WrappedBuilder<[MenuItemConfiguration]> {
    return wrapBuilder(MenuItemBuilder)
  }
}

// 定义一个MenuItem的构建器函数
@Builder
function MenuItemBuilder(configuration: MenuItemConfiguration) {
  Row() {
    // 显示菜单项的值
    Text(configuration.value)
    // 添加空白间隔
    Blank()
    // 如果有symbolIcon，则显示SymbolGlyph组件
    if (configuration.symbolIcon) {
      SymbolGlyph().attributeModifier(configuration.symbolIcon).fontSize(24)
    // 否则，如果有icon，则显示Image组件
    } else if (configuration.icon) {
      Image(configuration.icon).size({ width: 24, height: 24 })
    }
    // 添加空白间隔
    Blank(30)
    // 显示自定义内容修饰器的文本
    Text((configuration.contentModifier as MyMenuItemContentModifier).modifierText)
    // 添加空白间隔
    Blank(30)
    // 绘制一个三角形路径
    Path()
      .width('100px')
      .height('150px')
      .commands('M40 0 L80 100 L0 100 Z')
      .fillOpacity(0)
      .stroke(Color.Black)
      .strokeWidth(3)
  }
  // 点击菜单项时触发选择事件
  .onClick(() => {
    configuration.triggerSelect(configuration.index, configuration.value.valueOf().toString())
  })
}

// 定义一个Select组件的示例
@Entry
@Component
struct SelectExample {
  @State text: string = "Content Modifier Select"
  @State symbolModifier1: SymbolGlyphModifier = new SymbolGlyphModifier($r('sys.symbol.ohos_trash')).fontColor([Color.Gray]);
  @State symbolModifier2: SymbolGlyphModifier = new SymbolGlyphModifier($r('sys.symbol.exposure')).fontColor([Color.Gray]);
  build() {
    Column() {
      Row() {
        // 创建一个Select组件，包含两个菜单项
        Select([{ value: 'item1', icon: $r('app.media.icon'), symbolIcon: this.symbolModifier1 },
          { value: 'item1', icon: $r('app.media.icon'), symbolIcon: this.symbolModifier2 }])
          .value(this.text)
          // 选择菜单项时触发的事件
          .onSelect((index: number, text?: string) => {
            console.info('Select index:' + index)
            console.info('Select text:' + text)
          })
          // 应用自定义的菜单项内容修饰器
          .menuItemContentModifier(new MyMenuItemContentModifier("Content Modifier"))
      }
      // 设置Row组件的对齐方式为垂直居中，高度为50%
      .alignItems(VerticalAlign.Center).height('50%')
    }
  }
}

