DatePicker.code:
// xxx.ets
@Entry
@Component
struct DatePickerExample {
  @State isLunar: boolean = false // 状态变量，用于控制日期选择器显示公历或农历
  private selectedDate: Date = new Date('2021-08-08') // 初始选中的日期

  build() {
    Column() {
      Button('切换公历农历')
        .margin({ top: 30, bottom: 30 }) // 设置按钮的上下外边距为 30vp
        .onClick(() => {
          this.isLunar = !this.isLunar // 点击按钮时，切换 isLunar 状态变量
        })
      DatePicker({
        start: new Date('1970-1-1'), // 日期选择器的起始日期
        end: new Date('2100-1-1'), // 日期选择器的结束日期
        selected: this.selectedDate // 初始选中的日期
      })
        .disappearTextStyle({color: Color.Gray, font: {size: '16fp', weight: FontWeight.Bold}}) // 设置消失文本的样式
        .textStyle({color: '#ff182431', font: {size: '18fp', weight: FontWeight.Normal}}) // 设置普通文本的样式
        .selectedTextStyle({color: '#ff0000FF', font: {size: '26fp', weight: FontWeight.Regular}}) // 设置选中日期的文本样式
        .lunar(this.isLunar) // 根据 isLunar 状态变量显示公历或农历
        .onDateChange((value: Date) => {
          this.selectedDate = value // 日期变化时更新 selectedDate 状态变量
          console.info('select current date is: ' + value.toString()) // 在控制台输出当前选中的日期
        })
    }.width('100%') // 设置布局宽度为 100%
  }
}

