        .margin(30) // 设置按钮的外边距为30vp
        .onClick(() => { // 设置按钮的点击事件
          this.isMilitaryTime = !this.isMilitaryTime // 切换 `isMilitaryTime` 状态变量的值
        })
      TimePicker({
        selected: this.selectedTime, // 设置时间选择器的初始选中时间为 `selectedTime`
      })
        .useMilitaryTime(this.isMilitaryTime) // 根据 `isMilitaryTime` 的值决定时间选择器的显示格式
        .onChange((value: TimePickerResult) => { // 设置时间选择器的 `onChange` 事件
          if(value.hour >= 0) { // 如果小时值有效
            this.selectedTime.setHours(value.hour, value.minute) // 更新 `selectedTime` 状态变量
            console.info('select current date is: ' + JSON.stringify(value)) // 在控制台输出当前选择的时间
          }
        })
        .disappearTextStyle({color: Color.Red, font: {size: 15, weight: FontWeight.Lighter}}) // 设置未选中的时间文本样式
        .textStyle({color: Color.Black, font: {size: 20, weight: FontWeight.Normal}}) // 设置普通时间文本样式
        .selectedTextStyle({color: Color.Blue, font: {size: 30, weight: FontWeight.Bolder}}) // 设置选中时间文本样式
    }.width('100%') // 设置 Column 的宽度为100%
  }
}

