@Component
struct SearchExample {
  // 创建一个SearchController实例，用于控制搜索框的行为
  controller: SearchController = new SearchController()

  // 定义一个状态变量changeValue，用于存储用户输入的搜索内容
  @State changeValue: string = ''

  // 定义一个状态变量submitValue，用于存储提交的搜索内容
  @State submitValue: string = ''

  build() {
    Column() {
      // 创建一个Search组件，绑定changeValue作为输入值，占位符文本为'Type to search...'，使用controller控制搜索框
      Search({ value: this.changeValue, placeholder: 'Type to search...', controller: this.controller })
        // 设置搜索框左侧的搜索图标，使用SymbolGlyphModifier设置图标样式，图标颜色为红色
        .searchIcon(new SymbolGlyphModifier($r('sys.symbol.magnifyingglass')).fontColor([Color.Red]))
        // 设置搜索框右侧的取消按钮，按钮样式为常驻显示，图标颜色为绿色
        .cancelButton({
          style: CancelButtonStyle.CONSTANT,
          icon: new SymbolGlyphModifier($r('sys.symbol.xmark')).fontColor([Color.Green])
        })
        // 设置搜索框底部的搜索按钮文本为'SEARCH'
        .searchButton('SEARCH')
        // 设置搜索框的宽度为屏幕宽度的95%
        .width('95%')
        // 设置搜索框的高度为40vp
        .height(40)
        // 设置搜索框的背景颜色为浅灰色（#F5F5F5）
        .backgroundColor('#F5F5F5')
        // 设置搜索框占位符文本的颜色为灰色
        .placeholderColor(Color.Grey)
        // 设置搜索框占位符文本的字体大小为14，字重为400
        .placeholderFont({ size: 14, weight: 400 })
        // 设置搜索框输入文本的字体大小为14，字重为400
        .textFont({ size: 14, weight: 400 })
        // 设置搜索框的边距为10vp
        .margin(10)
    }
    // 设置Column的宽度为屏幕宽度
    .width('100%')
    // 设置Column的高度为屏幕高度
    .height('100%')
  }
}

