@Entry
@Component
struct textTimerStart {
  // 创建一个 TextTimerController 实例，用于控制计时器的启动和停止
  textTimerController: TextTimerController = new TextTimerController()

  // 定义计时器的时间格式，初始值为 'mm:ss.SS'，表示分钟、秒和毫秒
  @State format: string = 'mm:ss.SS'

  build() {
    Column() {
      // 创建一个 Scroll 组件，用于在内容超出高度时进行滚动
      Scroll()
        .height('20%') // 设置 Scroll 组件的高度为屏幕高度的 20%

      // 创建一个 TextTimer 组件，用于显示倒计时时间
      TextTimer({ 
        isCountDown: true, // 设置计时器为倒计时模式
        count: 30000, // 设置倒计时的总时间为 30000 毫秒（30 秒）
        controller: this.textTimerController // 绑定计时器控制器
      })
        .format(this.format) // 设置计时器的时间显示格式
        .fontColor(Color.Black) // 设置计时器文本颜色为黑色
        .fontSize(50) // 设置计时器文本字体大小为 50vp
        .onTimer((utc: number, elapsedTime: number) => {
          // 当计时器更新时触发的事件，输出当前的 UTC 时间和已过去的时间
          console.info('textTimer notCountDown utc is：' + utc + ', elapsedTime: ' + elapsedTime)
        })
        .onAppear(() => {
          // 当组件出现时触发的事件，启动计时器
          this.textTimerController.start()
        })
    }
  }
}

示例：该示例实现了一个包含两个简易秒表的界面，其中一个为倒计时器，另一个为正计时器。界面背景为浅灰色，计时器开始后会实时显示时间变化。倒计时器开始后，背景会变成黑色，正计时器开始后，背景会变成灰色。

布局属性：
- 整个界面采用Row布局，高度占据整个屏幕。
- 内部包含一个Column布局，宽度占据整个屏幕。
- 两个TextTimer组件分别用于倒计时和正计时，通过Column布局垂直排列。
- 按钮组采用Row布局，水平排列，按钮之间有10vp的间距，按钮组与计时器之间有20vp的间距。

组件的样式和外观：
- 计时器背景为一个圆形，倒计时器开始后背景为黑色（0xFF232323），正计时器开始后背景为灰色（0xFF717171），未开始时背景为浅灰色（0xFF929292）。
- 计时器内部的文本颜色为白色（Color.White）。
- 按钮的样式包括背景颜色、边框圆角、宽度和高度等属性，支持不同的样式展示。

组件的排列和嵌套关系：
- 整个界面采用Row布局，内部包含一个Column布局。
- Column布局中包含两个TextTimer组件和一个按钮组。
- 按钮组采用Row布局，水平排列，按钮之间有10vp的间距。

组件的功能和交互：
- 计时器开始后会实时显示时间变化，倒计时器显示剩余时间，正计时器显示已经过去的时间。
- 按钮组包含三个按钮：“start”、“pause”和“reset”，分别用于启动、暂停和重置计时器。
- 点击“start”按钮后，两个计时器开始计时；点击“pause”按钮后，两个计时器暂停计时；点击“reset”按钮后，两个计时器重置为初始状态。
// 自定义ContentModifier类，用于修改TextTimer组件的内容
class MyTextTimerModifier implements ContentModifier<TextTimerConfiguration> {
  constructor() {
  }
  // 应用内容修改器，返回一个WrappedBuilder对象
  applyContent() : WrappedBuilder<[TextTimerConfiguration]> {
    return wrapBuilder(buildTextTimer)
  }
}

// 构建TextTimer组件的Builder函数
@Builder function buildTextTimer(config: TextTimerConfiguration) {
  Column() {
    // 使用Stack布局，内容居中对齐
    Stack({ alignContent: Alignment.Center }) {
      // 绘制一个圆形背景，根据计时器状态设置不同的背景颜色
      Circle({ width: 150, height: 150 }).fill(config.started ? (config.isCountDown ? 0xFF232323 : 0xFF717171) : 0xFF929292)
      Column(){
        // 显示计时器类型（倒计时或正计时），文本颜色为白色
        Text(config.isCountDown ? "倒计时" : "正计时").fontColor(Color.White)
        // 显示计时器时间，文本颜色为白色
        Text(
          (config.isCountDown ? "剩余" : "已经过去了") + (config.isCountDown?
            (Math.max(config.count / 1000 - config.elapsedTime / 100,0)).toFixed(1) + "/" + (config.count / 1000).toFixed(0)
            :((config.elapsedTime / 100).toFixed(0))
          ) + "秒"
        ).fontColor(Color.White)
      }
    }
  }
}

