@Component
struct RatingExample {
  @State rating: number = 3.5 // 定义一个状态变量rating，初始值为3.5，用于存储当前评分值

  build() {
    Column() {
      Rating({ rating: this.rating, indicator: false }) // 创建一个Rating组件，初始评分值为当前rating值，indicator属性为false表示评分组件可交互
        .stars(5) // 设置评分组件的总星星数为5
        .stepSize(0.5) // 设置评分组件的步长为0.5，即每次评分变化的最小单位为0.5
        .starStyle({
          backgroundUri: '/common/imag1.png', // 设置评分组件的背景星星图片为/common/imag1.png
          foregroundUri: '/common/imag2.png', // 设置评分组件的前景星星图片为/common/imag2.png
          secondaryUri: '/common/imag3.png' // 设置评分组件的次级星星图片为/common/imag3.png
        })
        .margin({ top: 24 }) // 设置评分组件的顶部边距为24vp
        .onChange((value: number) => { // 监听评分组件的评分变化事件
          this.rating = value // 当评分变化时，更新rating状态变量的值为新的评分值
        })
      Text('current score is ' + this.rating) // 创建一个Text组件，显示当前评分值
        .fontSize(16) // 设置文本字体大小为16vp
        .fontColor('rgba(24,36,49,0.60)') // 设置文本字体颜色为rgba(24,36,49,0.60)
        .margin({ top: 16 }) // 设置文本组件的顶部边距为16vp
    }.width('100%').height('100%').backgroundColor('#F1F3F5') // 设置Column组件的宽度为100%，高度为100%，背景颜色为#F1F3F5
  }
}

@Entry
@Component
struct RatingExample {
  @State rating: number = 3.5 // 初始化评分值为3.5

  build() {
    Column() {
      Column() {
        Rating({ rating: this.rating, indicator: false }) // 创建一个可编辑的Rating组件，初始评分值为this.rating
          .stars(5) // 设置Rating组件的星星数量为5
          .stepSize(0.5) // 设置Rating组件的步长为0.5
          .margin({ top: 24 }) // 设置Rating组件的顶部外边距为24vp
          .onChange((value: number) => { // 当评分值改变时，触发onChange事件
            this.rating = value // 更新@State变量rating的值
          })
        Text('current score is ' + this.rating) // 显示当前评分值
          .fontSize(16) // 设置字体大小为16
          .fontColor('rgba(24,36,49,0.60)') // 设置字体颜色为rgba(24,36,49,0.60)
          .margin({ top: 16 }) // 设置顶部外边距为16vp
      }.width(360).height(113).backgroundColor('#FFFFFF').margin({ top: 68 }) // 设置评分输入部分的宽度为360vp，高度为113vp，背景颜色为#FFFFFF，顶部外边距为68vp

      Row() {
        Image('common/testImage.jpg') // 显示用户头像
          .width(40) // 设置宽度为40vp
          .height(40) // 设置高度为40vp
          .borderRadius(20) // 设置边框半径为20vp
          .margin({ left: 24 }) // 设置左侧外边距为24vp
        Column() {
          Text('Yue') // 显示用户名
            .fontSize(16) // 设置字体大小为16
            .fontColor('#182431') // 设置字体颜色为#182431
            .fontWeight(500) // 设置字体粗细为500
