              .fontSize(10) // 设置字体大小为10
              .fontColor('#182431') // 设置字体颜色为#182431
          }
        }.margin({ left: 12 }).alignItems(HorizontalAlign.Start) // 设置左侧外边距为12vp，对齐方式为左对齐

        Text('1st Floor') // 显示评论楼层
          .fontSize(10) // 设置字体大小为10
          .fontColor('#182431') // 设置字体颜色为#182431
          .position({ x: 295, y: 8 }) // 设置位置为(295, 8)
      }.width(360).height(56).backgroundColor('#FFFFFF').margin({ top: 64 }) // 设置用户评论部分的宽度为360vp，高度为56vp，背景颜色为#FFFFFF，顶部外边距为64vp
    }.width('100%').height('100%').backgroundColor('#F1F3F5') // 设置整个布局的宽度为100%，高度为100%，背景颜色为#F1F3F5
  }
}

