# Rating
接口描述：Rating(options?: { rating: number, indicator?: boolean })
接口参数：{'rating': {"type":"number","required":true,"description":"设置并接收评分值。取值范围：[0, stars]。小于0取0，大于stars取最大值stars。从API version 10开始，该参数支持双向绑定变量。","default":0}, 'indicator': {"type":"boolean","required":false,"description":"设置评分组件作为指示器使用，不可改变评分。","default":false}}
stars(value: number)
属性名称：stars
属性参数：{'value': {"type":"number","required":true,"description":"设置评分总数。","default":5}}
stepSize(value: number)
属性名称：stepSize
属性参数：{'value': {"type":"number","required":true,"description":"设置操作评级的步长。","default":0.5}}
示例：该组件实现了一个自定义评分条的功能，每个圆圈表示0.5分。评分条的布局宽度占据整个屏幕，高度设为50vp。评分条的垂直方向上被分为两个部分：评分圆圈和分值显示。评分圆圈以水平布局方式排列，圆圈之间的间距均匀分布，且对齐方式为居中对齐。
评分圆圈的样式包括背景颜色、宽度和高度等属性，支持不同的样式展示。评分圆圈的功能包括点击事件和状态效果，用户可以通过点击评分圆圈触发相应操作，评分圆圈也可以在启用或禁用状态下进行展示。
评分条的样式和外观通过自定义的 `MyRatingStyle` 类进行配置，支持不同的样式展示。评分条的功能包括评分指示器、评分总数和评分步长等属性的配置，用户可以通过按钮点击事件改变这些属性。
整个布局通过 Flex 布局保证评分圆圈在水平方向上有序排列，确保界面整洁美观。
// 定义一个自定义评分样式类，实现 `ContentModifier` 接口
class MyRatingStyle implements ContentModifier<RatingConfiguration> {
  name: string = "" // 样式名称
  style: number = 0 // 样式编号

  // 构造函数，初始化样式名称和编号
  constructor(value1: string, value2: number) {
    this.name = value1
    this.style = value2
  }

  // 应用内容样式，返回一个 `WrappedBuilder`
  applyContent(): WrappedBuilder<[RatingConfiguration]> {
    return wrapBuilder(buildRating)
  }
}

// 定义一个构建评分的函数，接收 `RatingConfiguration` 配置对象
@Builder function buildRating(config: RatingConfiguration) {
  Column() {
    Row() {
      // 第一个评分圆圈
      Circle({ width: 25, height: 25 })
        .fill(config.rating >= 0.4 ? Color.Black : Color.Red) // 根据评分设置圆圈颜色
        .onClick((event: ClickEvent) => {
          if (!config.indicator) { // 如果评分条可改变评分
            if (config.stepSize == 0.5) { // 如果评分步长为0.5
              config.triggerChange(0.5); // 触发评分改变事件，评分增加0.5
              return
            }
            if (config.stepSize == 1) { // 如果评分步长为1
              config.triggerChange(1); // 触发评分改变事件，评分增加1
              return
            }
          }
        }).visibility(config.stars >= 1 ? Visibility.Visible : Visibility.Hidden) // 根据评分总数设置圆圈可见性

      // 第二个评分圆圈
      Circle({ width: 25, height: 25 })
        .fill(config.rating >= 0.9 ? Color.Black : Color.Red)
        .onClick((event: ClickEvent) => {
          if (!config.indicator) {
            config.triggerChange(1);
          }
        }).visibility(config.stars >= 1 ? Visibility.Visible : Visibility.Hidden)

      // 第三个评分圆圈
      Circle({ width: 25, height: 25 })
        .fill(config.rating >= 1.4 ? Color.Black : Color.Red)
        .onClick((event: ClickEvent) => {
          if (!config.indicator) {
            if (config.stepSize == 0.5) {
              config.triggerChange(1.5);
              return
            }
            if (config.stepSize == 1) {
              config.triggerChange(2);
              return
            }
          }
        }).visibility(config.stars >= 2 ? Visibility.Visible : Visibility.Hidden).margin({left:10})

      // 第四个评分圆圈
      Circle({ width: 25, height: 25 })
        .fill(config.rating >= 1.9 ? Color.Black : Color.Red)
        .onClick((event: ClickEvent) => {
          if (!config.indicator) {
            config.triggerChange(2);
          }
        }).visibility(config.stars >= 2 ? Visibility.Visible : Visibility.Hidden)

      // 第五个评分圆圈
      Circle({ width: 25, height: 25 })
        .fill(config.rating >= 2.4 ? Color.Black : Color.Red)
        .onClick((event: ClickEvent) => {
          if (!config.indicator) {
            if (config.stepSize == 0.5) {
              config.triggerChange(2.5);
              return
            }
            if (config.stepSize == 1) {
              config.triggerChange(3);
              return
            }
          }
        }).visibility(config.stars >= 3 ? Visibility.Visible : Visibility.Hidden).margin({left:10})

      // 第六个评分圆圈
      Circle({ width: 25, height: 25 })
        .fill(config.rating >= 2.9 ? Color.Black : Color.Red)
        .onClick((event: ClickEvent) => {
          if (!config.indicator) {
            config.triggerChange(3);
          }
        }).visibility(config.stars >= 3 ? Visibility.Visible : Visibility.Hidden)

      // 第七个评分圆圈
      Circle({ width: 25, height: 25 })
        .fill(config.rating >= 3.4 ? Color.Black : Color.Red)
        .onClick((event: ClickEvent) => {
          if (!config.indicator) {
            if (config.stepSize == 0.5) {
              config.triggerChange(3.5);
              return
            }
            if (config.stepSize == 1) {
              config.triggerChange(4);
              return
            }
          }
        }).visibility(config.stars >= 4 ? Visibility.Visible : Visibility.Hidden).margin({left:10})

      // 第八个评分圆圈
      Circle({ width: 25, height: 25 })
        .fill(config.rating >= 3.9 ? Color.Black : Color.Red)
        .onClick((event: ClickEvent) => {
          if (!config.indicator) {
            config.triggerChange(4);
          }
        }).visibility(config.stars >= 4 ? Visibility.Visible : Visibility.Hidden)

      // 第九个评分圆圈
      Circle({ width: 25, height: 25 })
        .fill(config.rating >= 4.4 ? Color.Black : Color.Red)
        .onClick((event: ClickEvent) => {
          if (!config.indicator) {
            if (config.stepSize == 0.5) {
              config.triggerChange(4.5);
              return
            }
            if (config.stepSize == 1) {
              config.triggerChange(5);
              return
            }
          }
        }).visibility(config.stars >= 5 ? Visibility.Visible : Visibility.Hidden).margin({left:10})

      // 第十个评分圆圈
      Circle({ width: 25, height: 25 })
        .fill(config.rating >= 4.9 ? Color.Black : Color.Red)
        .onClick((event: ClickEvent) => {
          if (!config.indicator) {
            config.triggerChange(5);
          }
        }).visibility(config.stars >= 5 ? Visibility.Visible : Visibility.Hidden)
    }
    // 显示当前评分值
    Text("分值：" + config.rating)
  }
}

// 定义评分条示例组件
@Entry
@Component
struct ratingExample {
  @State rating: number = 0; // 当前评分值
  @State ratingIndicator: boolean = true; // 评分指示器状态，true表示不可改变评分
  @State ratingStars: number = 0; // 评分总数
  @State ratingStepsize: number = 0.5; // 评分步长
  @State ratingEnabled: boolean = true; // 评分条是否启用

  build() {
    Row() {
      Column() {
        // 创建评分条组件
        Rating({
          rating: 0, // 初始评分值
          indicator: this.ratingIndicator // 评分指示器状态
        })
          .stepSize(this.ratingStepsize) // 设置评分步长
          .stars(this.ratingStars) // 设置评分总数
          .backgroundColor(Color.Transparent) // 设置背景颜色为透明
          .width('100%') // 设置宽度为100%
          .height(50) // 设置高度为50vp
          .onChange((value: number) => { // 评分改变事件
            console.info('Rating change is' + value);
            this.rating = value // 更新当前评分值
          })
          .contentModifier(new MyRatingStyle("hello", 3)) // 应用自定义评分样式

        // 切换评分指示器状态的按钮
        Button(this.ratingIndicator ? "ratingIndicator : true" : "ratingIndicator : false")
          .onClick((event) => {
            if (this.ratingIndicator) {
              this.ratingIndicator = false
            } else {
              this.ratingIndicator = true
            }
          }).margin({top: 5})

        // 增加评分总数的按钮
        Button(this.ratingStars < 5 ? "ratingStars + 1, ratingStars =" + this.ratingStars : "ratingStars最大值为5")
          .onClick((event) => {
            if (this.ratingStars < 5) {
              this.ratingStars += 1
            }
          }).margin({top: 5})

        // 减少评分总数的按钮
        Button(this.ratingStars > 0 ? "ratingStars - 1, ratingStars =" + this.ratingStars : "ratingStars小于等于0时默认等于5")
          .onClick((event) => {
            if (this.ratingStars > 0) {
              this.ratingStars -= 1
            }
          }).margin({top: 5})

        // 切换评分步长的按钮
        Button(this.ratingStepsize == 0.5 ? "ratingStepsize : 0.5" : "ratingStepsize : 1")
          .onClick((event) => {
            if (this.ratingStepsize == 0.5) {
              this.ratingStepsize = 1
            } else {
              this.ratingStepsize = 0.5
            }
          }).margin({top: 5})
      }
      .width('100%') // 设置宽度为100%
      .height('100%') // 设置高度为100%
      .justifyContent(FlexAlign.Center) // 设置内容居中对齐
    }
    .height('100%') // 设置高度为100%
  }
}

示例：该组件通过Column布局实现了一个评分展示和交互界面。布局宽度占据整个屏幕，高度设为100%，背景颜色为#F1F3F5。组件的垂直方向上被分为两个部分：评分组件和文本显示组件。评分组件包含一个Rating组件，用于展示和调整评分，评分范围为0到5，步长为0.5。评分组件的星星样式通过自定义背景图片实现，背景图片分别为/common/imag1.png、/common/imag2.png和/common/imag3.png。评分组件的顶部边距为24vp。文本显示组件用于显示当前评分值，字体大小为16vp，字体颜色为rgba(24,36,49,0.60)，顶部边距为16vp。
评分组件支持用户通过点击或滑动来调整评分，评分值的变化会实时更新到文本显示组件中。整个布局通过Column布局保证评分组件和文本显示组件在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct RatingExample {
  @State rating: number = 3.5 // 定义一个状态变量rating，初始值为3.5，用于存储当前评分值

  build() {
    Column() {
      Rating({ rating: this.rating, indicator: false }) // 创建一个Rating组件，初始评分值为当前rating值，indicator属性为false表示评分组件可交互
        .stars(5) // 设置评分组件的总星星数为5
        .stepSize(0.5) // 设置评分组件的步长为0.5，即每次评分变化的最小单位为0.5
        .starStyle({
          backgroundUri: '/common/imag1.png', // 设置评分组件的背景星星图片为/common/imag1.png
          foregroundUri: '/common/imag2.png', // 设置评分组件的前景星星图片为/common/imag2.png
          secondaryUri: '/common/imag3.png' // 设置评分组件的次级星星图片为/common/imag3.png
        })
        .margin({ top: 24 }) // 设置评分组件的顶部边距为24vp
        .onChange((value: number) => { // 监听评分组件的评分变化事件
          this.rating = value // 当评分变化时，更新rating状态变量的值为新的评分值
        })
      Text('current score is ' + this.rating) // 创建一个Text组件，显示当前评分值
        .fontSize(16) // 设置文本字体大小为16vp
        .fontColor('rgba(24,36,49,0.60)') // 设置文本字体颜色为rgba(24,36,49,0.60)
        .margin({ top: 16 }) // 设置文本组件的顶部边距为16vp
    }.width('100%').height('100%').backgroundColor('#F1F3F5') // 设置Column组件的宽度为100%，高度为100%，背景颜色为#F1F3F5
  }
}

示例：该组件通过Column和Row布局实现了一个评分示例界面。布局宽度占据整个屏幕，高度设为100%，背景颜色为#F1F3F5。组件的垂直方向上被分为两个主要部分：评分输入部分和用户评论部分。

评分输入部分包含一个Rating组件和一个Text组件，Rating组件用于用户输入评分，Text组件用于显示当前评分值。Rating组件的宽度为360vp，高度为113vp，背景颜色为#FFFFFF，顶部外边距为68vp。Rating组件的星星数量为5，步长为0.5，顶部外边距为24vp。当评分值改变时，会触发onChange事件，更新@State变量rating的值，并更新Text组件的显示内容。Text组件的字体大小为16，字体颜色为rgba(24,36,49,0.60)，顶部外边距为16vp。

用户评论部分包含一个Row布局，其中包含一个Image组件、一个Column布局和一个Text组件。Image组件显示用户头像，宽度为40vp，高度为40vp，边框半径为20vp，左侧外边距为24vp。Column布局包含用户名和评分信息，用户名的字体大小为16，字体颜色为#182431，字体粗细为500。评分信息包含一个Rating组件和一个Text组件，Rating组件的评分值为3.5，不可编辑，顶部外边距为1vp，右侧外边距为8vp。Text组件显示评论日期，字体大小为10，字体颜色为#182431。Text组件显示评论楼层，字体大小为10，字体颜色为#182431，位置为(295, 8)。

整个布局通过Column和Row布局保证组件在垂直和水平方向上有序排列，确保界面整洁美观。
