@Builder function buildSlider(config: SliderConfiguration) {
  Row() {
    Column({space: 30}) {
      // 创建一个环形进度条，显示当前进度值
      Progress({value: config.value, total: config.max, type:ProgressType.Ring})
        .margin({ top:20 })

      // 创建一个按钮，点击后增加滑动条的值
      Button('增加').onClick(() => {
        config.value = config.value + config.step
        config.triggerChange(config.value, SliderChangeMode.Click)
      })
        .width(100) // 设置按钮宽度
        .height(25) // 设置按钮高度
        .fontSize(10) // 设置按钮字体大小
        .enabled(config.value<config.max) // 设置按钮是否启用，当值小于最大值时启用

      // 创建一个按钮，点击后减少滑动条的值
      Button('减少').onClick(() => {
        config.value = config.value - config.step
        config.triggerChange(config.value, SliderChangeMode.Click)
      })
        .width(100) // 设置按钮宽度
        .height(25) // 设置按钮高度
        .fontSize(10) // 设置按钮字体大小
        .enabled(config.value>config.min) // 设置按钮是否启用，当值大于最小值时启用

      // 创建一个滑动条，显示当前值，并支持拖动改变值
      Slider({
        value: config.value,
        min: config.min,
        max: config.max,
        step:config.step,
      })
        .width(config.max) // 设置滑动条宽度
        .visibility((config.contentModifier as MySliderStyle).showSlider?Visibility.Visible:Visibility.Hidden) // 根据配置显示或隐藏滑动条
        .showSteps(true) // 显示步长
        .onChange((value: number, mode: SliderChangeMode) => {
          config.triggerChange(value, mode)
        })

      // 显示当前滑动条的状态（Begin, Moving, End, Click）
      Text('当前状态：' + ((config.contentModifier as MySliderStyle).sliderChangeMode==0?"Begin"
        :((config.contentModifier as MySliderStyle).sliderChangeMode==1?"Moving"
          :((config.contentModifier as MySliderStyle).sliderChangeMode==2?"End"
            :((config.contentModifier as MySliderStyle).sliderChangeMode==3?"Click":"无")))))
        .fontSize(10) // 设置文本字体大小

      // 显示当前滑动条的进度值
      Text('进度值：' + config.value)
        .fontSize(10) // 设置文本字体大小

      // 显示滑动条的最小值
      Text('最小值：' + config.min)
        .fontSize(10) // 设置文本字体大小

      // 显示滑动条的最大值
      Text('最大值：' + config.max)
        .fontSize(10) // 设置文本字体大小

      // 显示滑动条的步长
      Text('步长：' + config.step)
        .fontSize(10) // 设置文本字体大小
    }
    .width('80%') // 设置列的宽度为父容器的80%
  }
  .width('100%') // 设置行的宽度为父容器的100%
}

// 定义一个类，用于配置滑动条的显示和状态
class MySliderStyle implements ContentModifier<SliderConfiguration> {
  showSlider:boolean = true // 是否显示滑动条
  sliderChangeMode:number = 0 // 滑动条的状态
  constructor(showSlider: boolean,sliderChangeMode:number) {
    this.showSlider = showSlider
    this.sliderChangeMode = sliderChangeMode
  }
  applyContent() : WrappedBuilder<[SliderConfiguration]> {
    return wrapBuilder(buildSlider)
  }
}

@Entry
@Component
struct SliderExample {
  @State showSlider:boolean = true // 是否显示滑动条
  @State sliderValue: number = 0 // 滑动条的当前值
  @State sliderMin: number = 10 // 滑动条的最小值
  @State sliderMax: number = 100 // 滑动条的最大值
  @State sliderStep: number = 20 // 滑动条的步长
  @State sliderChangeMode: number = 0 // 滑动条的状态

  build() {
    Column({ space: 8 }) {
      Row() {
        // 创建一个滑动条，显示当前值，并支持拖动改变值
        Slider({
          value: this.sliderValue,
          min: this.sliderMin,
          max: this.sliderMax,
          step:this.sliderStep,
        })
          .showSteps(true) // 显示步长
          .onChange((value: number, mode: SliderChangeMode) => {
            this.sliderValue = value
            this.sliderChangeMode = mode
            console.info('【SliderLog】value:' + value + 'mode:' + mode.toString())
          })
          .contentModifier(new MySliderStyle(this.showSlider,this.sliderChangeMode)) // 应用自定义样式
      }
      .width('100%') // 设置行的宽度为父容器的100%
    }
    .width('100%') // 设置列的宽度为父容器的100%
  }
}

