示例：该组件展示了一个通过点击按钮切换图片源的功能。布局宽度占据整个屏幕，内边距为20vp。组件的垂直方向上包含一个图片和一个按钮。图片的宽度为100vp，高度为100vp，按钮的宽度为100%，内边距为20vp。按钮的文本为“点击切换Image的src”，点击按钮时会切换图片的源。
图片的源可以是ResourceStr类型或ImageContent类型，通过@State变量imageSrcIndex来控制当前显示的图片源。当点击按钮时，imageSrcIndex会递增并取模于imageSrcList的长度，从而实现图片源的切换。
@Entry
@Component
struct ImageContentExample {
  // 定义一个状态变量imageSrcIndex，用于控制当前显示的图片源索引，初始值为0
  @State imageSrcIndex: number = 0;

  // 定义一个状态变量imageSrcList，用于存储图片源列表，包含一个ResourceStr类型和一个ImageContent类型
  @State imageSrcList: (ResourceStr | ImageContent)[] = [$r('app.media.app_icon'), ImageContent.EMPTY];

  build() {
    Column({ space: 10 }) {
      // 创建一个Image组件，显示当前索引对应的图片源，宽度为100vp，高度为100vp
      Image(this.imageSrcList[this.imageSrcIndex])
        .width(100)
        .height(100)

      // 创建一个Button组件，文本为“点击切换Image的src”，内边距为20vp，点击时触发onClick事件
      Button('点击切换Image的src')
        .padding(20)
        .onClick(() => {
          // 点击按钮时，imageSrcIndex递增并取模于imageSrcList的长度，实现图片源的切换
          this.imageSrcIndex = (this.imageSrcIndex + 1) % this.imageSrcList.length;
        })
    }
    // 设置Column组件的宽度为100%，内边距为20vp
    .width('100%')
    .padding(20)
  }
}

示例：该组件通过 Flex 布局实现了一个展示图片及其调整拉伸效果的界面。布局宽度占据整个屏幕，高度设为 100%，内边距为 0。组件的垂直方向上被分为多个部分，每个部分包含一个图片和一组按钮。每个图片组的图片以固定宽度和高度（200vp）展示，图片之间的间距为 5vp，且对齐方式为居中对齐。
图片的样式包括边框颜色和宽度（粉色，2vp），支持不同的图片适应方式（如包含、覆盖等）。图片组之间通过 Flex 组件进行分隔。按钮的功能包括点击事件和状态效果，用户可以通过点击按钮触发相应操作，按钮也可以在启用或禁用状态下进行展示。
整个布局通过 Flex 布局保证图片在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct Index {
  @State top: number = 40 // 定义图片顶部拉伸区域的初始值
  @State bottom: number = 5 // 定义图片底部拉伸区域的初始值
  @State left: number = 40 // 定义图片左侧拉伸区域的初始值
  @State right: number = 10 // 定义图片右侧拉伸区域的初始值

  build() {
    Column({ space: 5 }) { // 创建一个垂直布局，组件之间的间距为 5vp

      Image($r("app.media.sky")) // 加载名为 "sky" 的图片资源
        .width(200).height(200) // 设置图片的宽度和高度为 200vp
        .border({ width: 2, color: Color.Pink }) // 设置图片的边框宽度和颜色（粉色，2vp）
        .objectFit(ImageFit.Contain) // 设置图片的适应方式为包含（保持图片比例，尽可能填充区域）

      Image($r("app.media.sky")) // 加载名为 "sky" 的图片资源
        .resizable({ // 设置图片的可调整拉伸区域
          slice: {
            left: this.left, // 设置图片左侧拉伸区域的宽度
            right: this.right, // 设置图片右侧拉伸区域的宽度
            top: this.top, // 设置图片顶部拉伸区域的高度
            bottom: this.bottom // 设置图片底部拉伸区域的高度
          }
        })
        .width(200) // 设置图片的宽度为 200vp
        .height(200) // 设置图片的高度为 200vp
        .border({ width: 2, color: Color.Pink }) // 设置图片的边框宽度和颜色（粉色，2vp）
        .objectFit(ImageFit.Contain) // 设置图片的适应方式为包含（保持图片比例，尽可能填充区域）

      Row() { // 创建一个水平布局
        Button("add top to " + this.top).fontSize(10) // 创建一个按钮，点击后增加顶部拉伸区域的高度
          .onClick(() => {
            this.top += 2 // 每次点击增加 2vp
          })
        Button("add bottom to " + this.bottom).fontSize(10) // 创建一个按钮，点击后增加底部拉伸区域的高度
          .onClick(() => {
            this.bottom += 2 // 每次点击增加 2vp
          })
      }

      Row() { // 创建一个水平布局
        Button("add left to " + this.left).fontSize(10) // 创建一个按钮，点击后增加左侧拉伸区域的宽度
          .onClick(() => {
            this.left += 2 // 每次点击增加 2vp
          })
        Button("add right to " + this.right).fontSize(10) // 创建一个按钮，点击后增加右侧拉伸区域的宽度
          .onClick(() => {
            this.right += 2 // 每次点击增加 2vp
          })
      }

    }
    .justifyContent(FlexAlign.Start).width('100%').height('100%') // 设置布局的对齐方式为开始对齐，宽度为 100%，高度为 100%
  }
}

