            top: {anchor: "__container__", align: VerticalAlign.Top}, // 顶部对齐容器顶部
            left: {anchor: "__container__", align: HorizontalAlign.Start} // 左侧对齐容器左侧
          })
          .id("row1")
          .margin(10) // 设置外边距为10像素

        // 第二个矩形，黄色背景，位于第一个矩形的右侧
        Row(){Text('row2')}.justifyContent(FlexAlign.Center)
          .width(100).height(100)
          .backgroundColor("#FFCC00")
          .alignRules({
            left: {anchor: "row1", align: HorizontalAlign.End}, // 左侧对齐第一个矩形的右侧
            top: {anchor: "row1", align: VerticalAlign.Top} // 顶部对齐第一个矩形的顶部
          })
          .id("row2")

        // 第三个矩形，橙色背景，位于第一个矩形的下方
        Row(){Text('row3')}.justifyContent(FlexAlign.Center)
          .width(100).height(100)
          .backgroundColor("#FF6633")
          .alignRules({
            left: {anchor: "row1", align: HorizontalAlign.Start}, // 左侧对齐第一个矩形的左侧
            top: {anchor: "row1", align: VerticalAlign.Bottom} // 顶部对齐第一个矩形的底部
          })
          .id("row3")

        // 第四个矩形，浅橙色背景，位于第三个矩形的右侧，第二个矩形的下方，设置了10像素的margin
        Row(){Text('row4')}.justifyContent(FlexAlign.Center)
          .width(100).height(100)
          .backgroundColor("#FF9966")
          .alignRules({
            left: {anchor: "row3", align: HorizontalAlign.End}, // 左侧对齐第三个矩形的右侧
            top: {anchor: "row2", align: VerticalAlign.Bottom} // 顶部对齐第二个矩形的底部
          })
          .id("row4")
          .margin(10) // 设置外边距为10像素
      }
      .width(300).height(300) // 设置RelativeContainer的宽度和高度
      .margin({left: 50}) // 设置RelativeContainer的左侧外边距为50像素
      .border({width:2, color: "#6699FF"}) // 设置RelativeContainer的边框
    }
    .height('100%') // 设置Row的高度为100%
  }
}

List.code:
@Entry
@Component
struct ListExample {
  private arr: number[] = [] // 用于存储列表项数据的数组
  private scrollerForList: Scroller = new Scroller() // 用于控制列表滚动的 Scroller 对象

  aboutToAppear() {
    for (let i = 0; i < 20; i++) {
      this.arr.push(i) // 初始化列表项数据，添加 20 个数字到数组中
    }
  }

  build() {
    Column() {
      Row() {
        List({ space: 20, initialIndex: 3, scroller: this.scrollerForList }) {
          ForEach(this.arr, (item: number) => {
            ListItem() {
              Text('' + item) // 显示列表项的数字
                .width('100%').height(100).fontSize(16) // Text 组件的宽度、高度和字体大小
                .textAlign(TextAlign.Center) // 文本居中对齐
            }
            .borderRadius(10).backgroundColor(0xFFFFFF) // 列表项的边框圆角和背景颜色
            .width('60%') // 列表项的宽度
            .height('80%') // 列表项的高度
          }, (item: number) => JSON.stringify(item)) // 列表项的唯一标识符
        }
        .chainAnimation(true) // 启用列表项的链式动画
        .edgeEffect(EdgeEffect.Spring) // 启用弹性边缘效果
        .listDirection(Axis.Horizontal) // 设置列表为水平方向
        .height('100%') // 列表的高度
        .width('100%') // 列表的宽度
        .scrollSnapAlign(ScrollSnapAlign.CENTER) // 设置滚动对齐方式为居中对齐
        .borderRadius(10) // 列表的边框圆角
        .backgroundColor(0xDCDCDC) // 列表的背景颜色
      }
      .width('100%') // Row 组件的宽度
      .height('100%') // Row 组件的高度
      .backgroundColor(0xDCDCDC) // Row 组件的背景颜色
      .padding({ top: 10 }) // Row 组件的顶部内边距
    }
  }
}

