示例：该组件通过Grid布局实现了一个展示数字网格的界面。布局宽度占据整个屏幕，高度设为300vp，内边距为顶部5vp。组件的垂直方向上被分为两个部分，每个部分包含一个Grid布局。每个Grid布局中的GridItem以水平布局方式排列，GridItem之间的间距均匀分布，且对齐方式为居中对齐。
GridItem的样式包括背景颜色、字体大小、宽度和高度等属性，支持不同的样式展示。Grid布局的功能包括多选和滚动条隐藏，用户可以通过点击GridItem触发相应操作，GridItem也可以在选中或未选中状态下进行展示。
整个布局通过Column布局保证Grid布局在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct GridExample {
  @State numbers: String[] = ['0', '1', '2', '3', '4'] // 定义一个状态变量numbers，用于存储展示的数字
  scroller: Scroller = new Scroller() // 创建一个Scroller对象，用于Grid的滚动控制

  // 定义第一个GridLayoutOptions对象，设置常规尺寸和非规则索引
  layoutOptions1: GridLayoutOptions = {
    regularSize: [1, 1],        // 设置常规GridItem的尺寸为1x1
    irregularIndexes: [0, 6],   // 设置非规则GridItem的索引为0和6
  }

  // 定义第二个GridLayoutOptions对象，设置常规尺寸、非规则索引和非规则尺寸获取函数
  layoutOptions2: GridLayoutOptions = {
    regularSize: [1, 1],        // 设置常规GridItem的尺寸为1x1
    irregularIndexes: [0, 7],   // 设置非规则GridItem的索引为0和7
    onGetIrregularSizeByIndex: (index: number) => { // 定义非规则GridItem的尺寸获取函数
      if (index === 0) {
        return [1, 5]            // 如果索引为0，返回尺寸为1x5
      }
      return [1, index % 6 + 1] // 否则返回尺寸为1x(index % 6 + 1)
    }
  }

  build() {
    Column({ space: 5 }) { // 创建一个Column布局，设置子组件之间的间距为5vp
      Grid(this.scroller, this.layoutOptions1) { // 创建第一个Grid布局，使用scroller和layoutOptions1
        ForEach(this.numbers, (day: string) => { // 遍历numbers数组，生成GridItem
          ForEach(this.numbers, (day: string) => {
            GridItem() { // 创建GridItem
              Text(day) // 创建Text组件，显示数字
                .fontSize(16) // 设置字体大小为16
                .backgroundColor(0xF9CF93) // 设置背景颜色为0xF9CF93
                .width('100%') // 设置宽度为100%
                .height(80) // 设置高度为80vp
                .textAlign(TextAlign.Center) // 设置文本居中对齐
            }.selectable(false) // 设置GridItem不可选中
          }, (day: string) => day) // 设置GridItem的key
        }, (day: string) => day) // 设置GridItem的key
      }
      .columnsTemplate('1fr 1fr 1fr 1fr 1fr') // 设置Grid的列模板为5列，每列宽度相等
      .columnsGap(10) // 设置列间距为10vp
      .rowsGap(10) // 设置行间距为10vp
      .multiSelectable(true) // 设置Grid支持多选
      .scrollBar(BarState.Off) // 设置滚动条为隐藏
      .width('90%') // 设置Grid宽度为90%
      .backgroundColor(0xFAEEE0) // 设置背景颜色为0xFAEEE0
      .height(300) // 设置高度为300vp

      Text('scroll').fontColor(0xCCCCCC).fontSize(9).width('90%') // 创建一个Text组件，显示"scroll"，设置字体颜色、大小和宽度

      Grid(undefined, this.layoutOptions2) { // 创建第二个Grid布局，使用layoutOptions2
        ForEach(this.numbers, (day: string) => { // 遍历numbers数组，生成GridItem
          ForEach(this.numbers, (day: string) => {
            GridItem() { // 创建GridItem
              Text(day) // 创建Text组件，显示数字
                .fontSize(16) // 设置字体大小为16
                .backgroundColor(0xF9CF93) // 设置背景颜色为0xF9CF93
                .width('100%') // 设置宽度为100%
                .height(80) // 设置高度为80vp
                .textAlign(TextAlign.Center) // 设置文本居中对齐
            }
          }, (day: string) => day) // 设置GridItem的key
        }, (day: string) => day) // 设置GridItem的key
      }
      .columnsTemplate('1fr 1fr 1fr 1fr 1fr') // 设置Grid的列模板为5列，每列宽度相等
      .columnsGap(10) // 设置列间距为10vp
      .rowsGap(10) // 设置行间距为10vp
      .scrollBar(BarState.Off) // 设置滚动条为隐藏
      .width('90%') // 设置Grid宽度为90%
      .backgroundColor(0xFAEEE0) // 设置背景颜色为0xFAEEE0
      .height(300) // 设置高度为300vp
    }.width('100%').margin({ top: 5 }) // 设置Column的宽度为100%，顶部外边距为5vp
  }
}

示例：该组件通过 Stack 布局实现了一个包含多个嵌套滚动视图的界面。布局宽度占据整个屏幕，高度设为 100%，内边距为左右 10vp。组件的垂直方向上被分为多个部分，每个部分包含一个标题和一个列表。列表中的每个项包含一个 Grid 组件，用于展示不同类型的商品列表。

组件的样式包括背景颜色、字体大小、边框圆角（或半径）、宽度和高度等属性，支持不同的样式展示。组件的排列和嵌套关系通过 Stack、Column、Row、List、Grid 等组件实现，确保界面整洁美观。

组件的功能包括点击事件、滚动事件和嵌套滚动控制。用户可以通过点击按钮触发相应操作，如滚动到顶部。滚动事件通过 onScrollFrameBegin 和 onScrollStart、onScrollStop 等事件处理函数实现，控制滚动行为和嵌套滚动优先级。
@Entry
@Component
struct GridExample {
  @State colors: number[] = [0xFFC0CB, 0xDA70D6, 0x6B8E23, 0x6A5ACD, 0x00FFFF, 0x00FF7F]
  @State numbers: number[] = []
  @State translateY: number = 0
  private scroller: Scroller = new Scroller()
  private gridScroller: Scroller = new Scroller()
  private touchDown: boolean = false
  private listTouchDown: boolean = false
  private scrolling: boolean = false

  // 初始化数据，生成 100 个数字
  aboutToAppear() {
    for (let i = 0; i < 100; i++) {
      this.numbers.push(i)
    }
  }

  build() {
    Stack() {
      Column() {
        Row() {
          Text('Head')
        }

        Column() {
          List({ scroller: this.scroller }) {
            ListItem() {
              Grid() {
                GridItem() {
                  Text('GoodsTypeList1')
                }
                .backgroundColor(this.colors[0])
                .columnStart(0)
                .columnEnd(1)

                GridItem() {
                  Text('GoodsTypeList2')
                }
                .backgroundColor(this.colors[1])
                .columnStart(0)
                .columnEnd(1)

                GridItem() {
                  Text('GoodsTypeList3')
                }
                .backgroundColor(this.colors[2])
                .columnStart(0)
                .columnEnd(1)

                GridItem() {
                  Text('GoodsTypeList4')
                }
                .backgroundColor(this.colors[3])
                .columnStart(0)
                .columnEnd(1)

                GridItem() {
                  Text('GoodsTypeList5')
                }
                .backgroundColor(this.colors[4])
                .columnStart(0)
                .columnEnd(1)
              }
              .scrollBar(BarState.Off)
              .columnsGap(15)
              .rowsGap(10)
              .rowsTemplate('1fr 1fr 1fr 1fr 1fr')
              .columnsTemplate('1fr')
              .width('100%')
              .height(200)
            }

            ListItem() {
              Grid(this.gridScroller) {
                ForEach(this.numbers, (item: number) => {
                  GridItem() {
                    Text(item + '')
                      .fontSize(16)
                      .backgroundColor(0xF9CF93)
                      .width('100%')
                      .height('100%')
                      .textAlign(TextAlign.Center)
                  }
                  .width('100%')
                  .height(40)
                  .shadow({ radius: 10, color: '#909399', offsetX: 1, offsetY: 1 })
                  .borderRadius(10)
                  .translate({ x: 0, y: this.translateY })
                }, (item: string) => item)
              }
              .columnsTemplate('1fr 1fr')
              .friction(0.3)
              .columnsGap(15)
              .rowsGap(10)
              .scrollBar(BarState.Off)
              .width('100%')
              .height('100%')
              .layoutDirection(GridDirection.Column)
              .nestedScroll({
                scrollForward: NestedScrollMode.PARENT_FIRST,
                scrollBackward: NestedScrollMode.SELF_FIRST
              })
              .onTouch((event: TouchEvent) => {
                if (event.type == TouchType.Down) {
                  this.listTouchDown = true
                } else if (event.type == TouchType.Up) {
                  this.listTouchDown = false
                }
              })
            }
          }
          .scrollBar(BarState.Off)
          .edgeEffect(EdgeEffect.None)
          .onTouch((event: TouchEvent) => {
            if (event.type == TouchType.Down) {
              this.touchDown = true
            } else if (event.type == TouchType.Up) {
              this.touchDown = false
            }
          })
          .onScrollFrameBegin((offset: number, state: ScrollState) => {
            if (this.scrolling && offset > 0) {
              let newOffset = this.scroller.currentOffset().yOffset
              if (newOffset >= 590) {
                this.gridScroller.scrollBy(0, offset)
                return { offsetRemain: 0 }
              } else if (newOffset + offset > 590) {
                this.gridScroller.scrollBy(0, newOffset + offset - 590)
                return { offsetRemain: 590 - newOffset }
              }
            }
            return { offsetRemain: offset }
          })
          .onScrollStart(() => {
            if (this.touchDown && !this.listTouchDown) {
              this.scrolling = true
            }
          })
          .onScrollStop(() => {
            this.scrolling = false
          })
        }
        .width('100%')
        .height('100%')
        .padding({ left: 10, right: 10 })
      }

      Row() {
        Text('Top')
          .width(30)
          .height(30)
          .borderRadius(50)
      }
      .padding(5)
      .borderRadius(50)
      .backgroundColor('#ffffff')
      .shadow({ radius: 10, color: '#909399', offsetX: 1, offsetY: 1 })
      .margin({ right: 22, bottom: 15 })
      .onClick(() => {
        this.scroller.scrollTo({ xOffset: 0, yOffset: 0 })
        this.gridScroller.scrollTo({ xOffset: 0, yOffset: 0 })
      })
    }
    .align(Alignment.BottomEnd)
  }
}

示例：该组件通过Grid布局实现了一个可拖拽的网格界面。布局宽度占据整个屏幕的90%，高度设为300vp，内边距为顶部5vp。组件的垂直方向上包含一个Grid组件，Grid组件内部包含多个GridItem组件。每个GridItem组件包含一个Text组件，用于显示数字。Grid组件的列数为3列，列间距为10vp，行间距为10vp。

Grid组件的样式包括背景颜色为0xFAEEE0，GridItem组件的样式包括背景颜色为0xF9CF93，字体大小为16，宽度为80vp，高度为80vp，文本居中对齐。

组件的功能包括拖拽事件和拖拽完成事件。用户可以通过拖拽GridItem组件来改变其在Grid中的位置。拖拽过程中会显示一个自定义的拖拽图片，拖拽完成后会交换数组中对应元素的位置。
@Entry
@Component
struct GridExample {
  @State numbers: string[] = [] // 存储网格中显示的数字
  scroller: Scroller = new Scroller() // 用于滚动Grid组件
  @State text: string = 'drag' // 用于存储拖拽过程中显示的文本

  // 构建拖拽过程中显示的图片
  @Builder pixelMapBuilder() { 
    Column() {
      Text(this.text)
        .fontSize(16) // 设置字体大小
        .backgroundColor(0xF9CF93) // 设置背景颜色
        .width(80) // 设置宽度
        .height(80) // 设置高度
        .textAlign(TextAlign.Center) // 设置文本居中对齐
    }
  }

  // 组件初始化时填充numbers数组
  aboutToAppear() {
    for (let i = 1;i <= 15; i++) {
      this.numbers.push(i + '')
    }
  }

  // 交换数组中两个元素的位置
  changeIndex(index1: number, index2: number) { 
    let temp: string;
    temp = this.numbers[index1];
    this.numbers[index1] = this.numbers[index2];
    this.numbers[index2] = temp;
  }

  // 构建组件UI
  build() {
    Column({ space: 5 }) {
      Grid(this.scroller) {
        ForEach(this.numbers, (day: string) => {
          GridItem() {
            Text(day)
              .fontSize(16) // 设置字体大小
              .backgroundColor(0xF9CF93) // 设置背景颜色
              .width(80) // 设置宽度
              .height(80) // 设置高度
              .textAlign(TextAlign.Center) // 设置文本居中对齐
          }
        })
      }
      .columnsTemplate('1fr 1fr 1fr') // 设置列模板，3列
      .columnsGap(10) // 设置列间距
      .rowsGap(10) // 设置行间距
      .width('90%') // 设置宽度为屏幕的90%
      .backgroundColor(0xFAEEE0) // 设置背景颜色
      .height(300) // 设置高度
      .editMode(true) // 设置Grid进入编辑模式，允许拖拽
      .onItemDragStart((event: ItemDragInfo, itemIndex: number) => { 
        this.text = this.numbers[itemIndex] // 设置拖拽过程中显示的文本
        return this.pixelMapBuilder() // 返回拖拽过程中显示的图片
      })
      .onItemDrop((event: ItemDragInfo, itemIndex: number, insertIndex: number, isSuccess: boolean) => { 
        if (!isSuccess || insertIndex >= this.numbers.length) {
          return
        }
        console.info('beixiang' + itemIndex + '', insertIndex + '') 
        this.changeIndex(itemIndex, insertIndex) // 交换数组中两个元素的位置
      })
    }.width('100%').margin({ top: 5 }) // 设置Column的宽度为100%，顶部边距为5vp
  }
}


# 声明式UI描述
ArkTS以声明方式组合和扩展组件来描述应用程序的UI，同时还提供了基本的属性、事件和子组件配置方法。

## 创建组件
根据组件构造方法的不同，创建组件包含有参数和无参数两种方式。

### 无参数
如果组件的接口定义没有包含必选构造参数，则组件后面的“()”不需要配置任何内容。例如，Divider组件不包含构造参数。
```ets
Column() {
  Text('item 1')
  Divider()
  Text('item 2')
}
```

### 有参数
- Image组件的必选参数src。
```ets
Image('https://xyz/test.jpg')
```
- Text组件的非必选参数content。
```ets
// string类型的参数
Text('test')
// $r形式引入应用资源，可应用于多语言场景
Text($r('app.string.title_value'))
// 无参数形式
Text()
```
- 变量或表达式也可以用于参数赋值，其中表达式返回的结果类型必须满足参数类型要求。
例如，设置变量或表达式来构造Image和Text组件的参数。
```ets
Image(this.imagePath)
Image('https://' + this.imageUrl)
Text(`count: ${this.count}`)
```

## 配置属性
属性方法以“.”链式调用的方式配置系统组件的样式和其他属性，建议每个属性方法单独写一行。

- 设置Text组件的字体大小。
```ets
Text('test')
  .fontSize(20)
```
- 配置组件的多个属性。
```ets
Image('test.jpg')
  .alt('error.jpg')
  .width(100)
  .height(100)
```
- 除了直接传递常量参数外，还可以传递变量或表达式。
```ets
Text('hello')
  .fontSize(this.size)
Image('test.jpg')
  .width(this.count % 2 === 0 ? 100 : 200)
  .height(this.offset + 100)
```
- 对于系统组件，ArkUI还为其属性预定义了一些枚举类型供开发者调用，枚举类型可以作为参数传递，但必须满足参数类型要求。
例如，可以按以下方式配置Text组件的颜色和字体样式。
```ets
Text('hello')
  .fontSize(20)
  .fontColor(Color.Red)
  .fontWeight(FontWeight.Bold)
```

## 配置事件
事件方法以“.”链式调用的方式配置系统组件支持的事件，建议每个事件方法单独写一行。

- 使用箭头函数配置组件的事件方法。
```ets
Button('Click me')
  .onClick(() => {
    this.myText = 'ArkUI';
  })
```
- 使用组件的成员函数配置组件的事件方法，需要bind this。ArkTS语法不推荐使用成员函数配合bind this去配置组件的事件方法。
```ets
myClickHandler(): void {
  this.counter += 2;
}
...
Button('add counter')
  .onClick(this.myClickHandler.bind(this))
```
- 使用声明的箭头函数，可以直接调用，不需要bind this。
```ets
fn = () => {
  console.info(`counter: ${this.counter}`)
  this.counter++
}
...
Button('add counter')
  .onClick(this.fn)
```

## 配置子组件
如果组件支持子组件配置，则需在尾随闭包"{...}"中为组件添加子组件的UI描述。Column、Row、Stack、Grid、List等组件都是容器组件。

- 容器组件均支持子组件配置，可以实现相对复杂的多级嵌套。
```ets
Column() {
  Row() {
    Image('test1.jpg')
      .width(100)
      .height(100)
    Button('click +1')
      .onClick(() => {
        console.info('+1 clicked!');
      })
  }
  .width('100%')
}
```
