@Entry
@Component
struct TabContentExample {
  @State fontColor: string = '#182431' // 未选中标签页的字体颜色
  @State selectedFontColor: string = '#007DFF' // 选中标签页的字体颜色
  @State currentIndex: number = 0 // 当前选中的标签页索引
  private controller: TabsController = new TabsController() // Tabs 组件的控制器

  @Builder tabBuilder(index: number) {
    Column() {
      Image(this.currentIndex === index ? '/common/public_icon_on.svg' : '/common/public_icon_off.svg')
        .width(24) // 图标的宽度
        .height(24) // 图标的高度
        .margin({ bottom: 4 }) // 图标的底部边距
        .objectFit(ImageFit.Contain) // 图标的对象适应方式
      Text('Tab')
        .fontColor(this.currentIndex === index ? this.selectedFontColor : this.fontColor) // 根据当前选中的标签页设置字体颜色
        .fontSize(10) // 字体大小
        .fontWeight(500) // 字体粗细
        .lineHeight(14) // 行高
    }.width('100%').height('100%').justifyContent(FlexAlign.Center) // 标签栏内容的布局方式
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start, controller: this.controller }) {
        TabContent()
          .tabBar(this.tabBuilder(0)) // 第一个标签页的标签栏内容
        TabContent()
          .tabBar(this.tabBuilder(1)) // 第二个标签页的标签栏内容
        TabContent()
          .tabBar(this.tabBuilder(2)) // 第三个标签页的标签栏内容
        TabContent()
          .tabBar(this.tabBuilder(3)) // 第四个标签页的标签栏内容
      }
      .vertical(true) // 标签栏垂直排列
      .barWidth(96) // 标签栏的宽度
      .barHeight(414) // 标签栏的高度
      .onChange((index: number) => {
        this.currentIndex = index // 更新当前选中的标签页索引
      })
      .width(96) // Tabs 组件的宽度
      .height(414) // Tabs 组件的高度
      .backgroundColor('#F1F3F5') // Tabs 组件的背景颜色
      .margin({ top: 52 }) // Tabs 组件的顶部边距
    }.width('100%') // 整个布局的宽度
  }
}

