# TabContent
接口描述：TabContent()
接口参数：{}
设置组件自身的宽度，缺省时使用元素自身内容需要的宽度。若子组件的宽大于父组件的宽，则会画出父组件的范围。从API version 10开始，该接口支持calc计算特性。
属性名称：width
属性参数：{'value': {"type":"Length","required":true,"description":"要设置的组件宽度。单位：vp","default":null}}
设置TabBar上显示内容。
属性名称：tabBar
属性参数：{'value': {"type":["string","Resource","CustomBuilder","object"],"required":true,"description":"TabBar上显示的内容。如果icon采用svg格式图源，则要求svg图源删除其自有宽高属性值。如采用带有自有宽高属性的svg图源，icon大小则是svg本身内置的宽高属性值大小。设置的内容超出tabbar页签时进行裁切。","default":null}}
设置组件的基准尺寸。
属性名称：flexBasis
属性参数：{'value': {"type":["number","string"],"required":true,"description":"设置组件在父容器主轴方向上的基准尺寸。不支持百分比设置。","default":"auto"}}
设置文本的文本行高，设置值不大于0时，不限制文本行高，自适应字体大小。
属性名称：lineHeight
属性参数：{'value': {"type":["number","string","Resource"],"required":true,"description":"文本行高，为number类型时单位为fp。","default":null}}
对子组件进行重新布局。
属性名称：layoutWeight
属性参数：{'value': {"type":["number","string"],"required":true,"description":"父容器尺寸确定时，设置了layoutWeight属性的子元素与兄弟元素占主轴尺寸按照权重进行分配，忽略元素本身尺寸设置，表示自适应占满剩余空间。默认值：0。仅在Row/Column/Flex布局中生效。可选值为大于等于0的数字，或者可以转换为数字的字符串。","default":null}}
设置组件自身的高度，缺省时使用元素自身内容需要的高度。若子组件的高大于父组件的高，则会画出父组件的范围。从API version 10开始，该接口支持calc计算特性。
属性名称：height
属性参数：{'value': {"type":"Length","required":true,"description":"要设置的组件高度。单位：vp","default":null}}
设置文本装饰线样式及其颜色。
属性名称：decoration
属性参数：{'value': {"type":"DecorationStyleInterface","required":true,"description":"文本装饰线样式对象。默认值：{ type: TextDecorationType.None, color: Color.Black, style: TextDecorationStyle.SOLID } 说明：style参数不支持卡片能力。","default":"{ type: TextDecorationType.None, color: Color.Black, style: TextDecorationStyle.SOLID } "}}
示例：该组件通过 Flex 布局实现了一个带有标签页（Tabs）的界面。布局宽度占据整个屏幕，高度设为 414vp，内边距为顶部 52vp。组件的垂直方向上包含一个 Tabs 组件，Tabs 组件的标签栏位于顶部，标签栏的宽度为 96vp，高度为 414vp，背景颜色为 #F1F3F5。每个标签页的内容通过 TabContent 组件定义，标签页的标签栏内容通过自定义的 tabBuilder 方法生成。

标签栏的内容包括一个图标和一个文本，图标根据当前选中的标签页显示不同的图标（选中时显示 public_icon_on.svg，未选中时显示 public_icon_off.svg），图标的宽度为 24vp，高度为 24vp，对象适应方式为 contain，底部边距为 4vp。文本内容为 "Tab"，字体颜色根据当前选中的标签页显示不同的颜色（选中时为 #007DFF，未选中时为 #182431），字体大小为 10vp，字体粗细为 500，行高为 14vp。

标签页的切换通过 Tabs 组件的 onChange 事件实现，当用户切换标签页时，currentIndex 状态变量会更新为当前选中的标签页索引。整个布局通过 Flex 布局保证标签页在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct TabContentExample {
  @State fontColor: string = '#182431' // 未选中标签页的字体颜色
  @State selectedFontColor: string = '#007DFF' // 选中标签页的字体颜色
  @State currentIndex: number = 0 // 当前选中的标签页索引
  private controller: TabsController = new TabsController() // Tabs 组件的控制器

  @Builder tabBuilder(index: number) {
    Column() {
      Image(this.currentIndex === index ? '/common/public_icon_on.svg' : '/common/public_icon_off.svg')
        .width(24) // 图标的宽度
        .height(24) // 图标的高度
        .margin({ bottom: 4 }) // 图标的底部边距
        .objectFit(ImageFit.Contain) // 图标的对象适应方式
      Text('Tab')
        .fontColor(this.currentIndex === index ? this.selectedFontColor : this.fontColor) // 根据当前选中的标签页设置字体颜色
        .fontSize(10) // 字体大小
        .fontWeight(500) // 字体粗细
        .lineHeight(14) // 行高
    }.width('100%').height('100%').justifyContent(FlexAlign.Center) // 标签栏内容的布局方式
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start, controller: this.controller }) {
        TabContent()
          .tabBar(this.tabBuilder(0)) // 第一个标签页的标签栏内容
        TabContent()
          .tabBar(this.tabBuilder(1)) // 第二个标签页的标签栏内容
        TabContent()
          .tabBar(this.tabBuilder(2)) // 第三个标签页的标签栏内容
        TabContent()
          .tabBar(this.tabBuilder(3)) // 第四个标签页的标签栏内容
      }
      .vertical(true) // 标签栏垂直排列
      .barWidth(96) // 标签栏的宽度
      .barHeight(414) // 标签栏的高度
      .onChange((index: number) => {
        this.currentIndex = index // 更新当前选中的标签页索引
      })
      .width(96) // Tabs 组件的宽度
      .height(414) // Tabs 组件的高度
      .backgroundColor('#F1F3F5') // Tabs 组件的背景颜色
      .margin({ top: 52 }) // Tabs 组件的顶部边距
    }.width('100%') // 整个布局的宽度
  }
}

