import { Chip, ChipSize, SymbolGlyphModifier } from '@kit.ArkUI';

@Entry
@Component
struct Index {
  @State isActivated: boolean = false; // 定义一个状态变量 isActivated，用于控制 Chip 组件的激活状态

  build() {
    Column({ space: 10 }) { // 使用 Column 布局，设置子组件之间的间距为 10vp
      Chip({
        prefixIcon: {
          src: $r('app.media.chips'), // 设置 Chip 组件前缀图标的资源路径
          size: { width: 16, height: 16 }, // 设置前缀图标的宽度和高度为 16vp
          fillColor: Color.Blue, // 设置前缀图标的填充颜色为蓝色
          activatedFillColor: $r('sys.color.ohos_id_color_text_primary_contrary') // 设置激活状态下前缀图标的填充颜色为系统定义的颜色
        },
        prefixSymbol: {
          normal: new SymbolGlyphModifier($r('sys.symbol.ohos_star')).fontSize(16).fontColor([Color.Green]), // 设置 Chip 组件前缀符号的正常状态，使用系统符号资源，字体大小为 16vp，字体颜色为绿色
          activated: new SymbolGlyphModifier($r('sys.symbol.ohos_star')).fontSize(16).fontColor([Color.Red]), // 设置 Chip 组件前缀符号的激活状态，使用系统符号资源，字体大小为 16vp，字体颜色为红色
        },
        label: {
          text: "操作块", // 设置 Chip 组件的标签文本为 "操作块"
          fontSize: 12, // 设置标签文本的字体大小为 12vp
          fontColor: Color.Blue, // 设置标签文本的字体颜色为蓝色
          activatedFontColor: $r('sys.color.ohos_id_color_text_primary_contrary'), // 设置激活状态下标签文本的字体颜色为系统定义的颜色
          fontFamily: "HarmonyOS Sans", // 设置标签文本的字体为 HarmonyOS Sans
          labelMargin: { left: 20, right: 30 }, // 设置标签文本的左右边距分别为 20vp 和 30vp
        },
        size: ChipSize.NORMAL, // 设置 Chip 组件的大小为正常大小
        allowClose: true, // 允许 Chip 组件显示关闭按钮
        enabled: true, // 设置 Chip 组件为启用状态
        activated: this.isActivated, // 根据 isActivated 状态变量设置 Chip 组件的激活状态
        backgroundColor: $r('sys.color.ohos_id_color_button_normal'), // 设置 Chip 组件的背景颜色为系统定义的颜色
        activatedBackgroundColor: $r('sys.color.ohos_id_color_emphasize'), // 设置激活状态下 Chip 组件的背景颜色为系统定义的颜色
        borderRadius: $r('sys.float.ohos_id_corner_radius_button'), // 设置 Chip 组件的边框圆角为系统定义的圆角
        onClose:()=>{
          console.log("chip on close") // 定义 Chip 组件的关闭事件回调函数，打印 "chip on close"
        },
        onClicked:()=>{
          console.log("chip on clicked") // 定义 Chip 组件的点击事件回调函数，打印 "chip on clicked"
        }
      })

      Button('改变激活状态').onClick(()=>{
        this.isActivated = !this.isActivated; // 定义 Button 组件的点击事件回调函数，切换 isActivated 状态变量的值
      })
    }
  }
}

