import { Chip, ChipSize, LengthMetrics } from '@kit.ArkUI'; // 导入 Chip 组件及其相关属性

@Entry
@Component
struct ChipPage {
  @State message: string = 'Hello World'; // 定义一个状态变量 message，初始值为 'Hello World'

  build() {
    Column() {
      Chip({
        direction: Direction.Rtl, // 设置 Chip 组件的布局方向为从右到左（镜像化）
        prefixIcon: {
          src: $r('app.media.chips'), // 设置前缀图标的资源路径
          size: { width: 16, height: 16 }, // 设置前缀图标的宽度和高度
          fillColor: Color.Red, // 设置前缀图标的填充颜色为红色
        },
        label: {
          text: "操作块", // 设置 Chip 组件的标签文本
          fontSize: 12, // 设置标签文本的字体大小
          fontColor: Color.Blue, // 设置标签文本的字体颜色为蓝色
          fontFamily: "HarmonyOS Sans", // 设置标签文本的字体族
          localizedLabelMargin: { start: LengthMetrics.vp(20), end: LengthMetrics.vp(20) }, // 设置标签文本的左右边距
        },
        suffixIcon: {
          src: $r('app.media.close'), // 设置后缀图标的资源路径
          size: { width: 16, height: 16 }, // 设置后缀图标的宽度和高度
          fillColor: Color.Red, // 设置后缀图标的填充颜色为红色
        },
        size: ChipSize.NORMAL, // 设置 Chip 组件的大小为正常尺寸
        allowClose: false, // 设置 Chip 组件是否允许关闭
        enabled: true, // 设置 Chip 组件是否启用
        backgroundColor: $r('sys.color.ohos\_id\_color\_button\_normal'), // 设置 Chip 组件的背景颜色，使用系统资源
        borderRadius: $r('sys.float.ohos\_id\_corner\_radius\_button') // 设置 Chip 组件的边框圆角，使用系统资源
      })
    }.justifyContent(FlexAlign.Center) // 设置 Column 组件的内容居中对齐
    .width('100%') // 设置 Column 组件的宽度为 100%
    .height('100%') // 设置 Column 组件的高度为 100%
  }
}

