          }.width('100%').backgroundColor(0xdcdcdc) // 设置Column的宽度为100%，背景颜色为0xdcdcdc
        }.width('100%').margin({ top: 5 }) // 设置Column的宽度为100%，上边距为5vp
      }.height('85%') // 设置Scroll的高度为85%

      Button('点击切换config.enableloading').onClick(() => {
        this.clickFlag++ // 增加点击标志
