示例：该组件实现了一个自定义样式的按钮，通过自定义样式类 `MyButtonStyle` 实现了按钮的圆圈样式替换。布局宽度占据整个屏幕，高度设为 100%，内边距为 0。组件的垂直方向上被分为两个部分：一个自定义样式的按钮和一个开关控件。按钮的样式包括背景颜色、宽度和高度等属性，支持不同的样式展示。按钮组之间通过 Flex 组件进行分隔。按钮的功能包括点击事件和状态效果，用户可以通过点击按钮触发相应操作，按钮也可以在启用或禁用状态下进行展示。开关控件用于控制按钮的启用或禁用状态。整个布局通过 Flex 布局保证按钮在垂直方向上有序排列，确保界面整洁美观。
// 自定义样式类，实现按钮的圆圈样式替换
class MyButtonStyle implements ContentModifier<ButtonConfiguration> {
  x: number = 0 // 按钮点击位置的x坐标
  y: number = 0 // 按钮点击位置的y坐标
  selectedColor: Color = Color.Black // 按钮按压时的颜色

  // 构造函数，初始化按钮的位置和颜色
  constructor(x: number, y: number, ColorType: Color) {
    this.x = x
    this.y = y
    this.selectedColor = ColorType
  }

  // 应用自定义样式，返回一个构建器
  applyContent(): WrappedBuilder<[ButtonConfiguration]> {
    return wrapBuilder(buildButton1)
  }
}

// 构建器函数，用于构建自定义样式的按钮
@Builder function buildButton1(config: ButtonConfiguration) {
  Column({ space: 30 }) {
    // 显示按钮的启用状态
    Text(config.enabled ? "enabled true" : "enabled false")
    // 显示按钮的按压状态
    Text('圆圈状态' + (config.pressed ? "（ 按压 ）" : "（ 非按压 ）"))
    // 显示按钮点击位置的x坐标
    Text('点击位置x坐标：' + (config.enabled ? (config.contentModifier as MyButtonStyle).x : "0"))
    // 显示按钮点击位置的y坐标
    Text('点击位置y坐标：' + (config.enabled ? (config.contentModifier as MyButtonStyle).y : "0"))
    // 绘制一个圆圈，根据按压状态改变颜色
    Circle({ width: 50, height: 50 })
      .fill(config.pressed ? (config.contentModifier as MyButtonStyle).selectedColor : Color.Black)
      .gesture(
        // 添加点击手势，触发按钮点击事件
        TapGesture({ count: 1 }).onAction((event: GestureEvent) => {
          config.triggerClick(event.fingerList[0].localX, event.fingerList[0].localY)
        })
      ).opacity(config.enabled ? 1 : 0.1) // 根据按钮启用状态设置透明度
  }
}

// 入口组件，定义按钮示例
@Entry
@Component
struct ButtonExample {
  @State buttonEnabled: boolean = true; // 按钮的启用状态
  @State positionX: number = 0 // 按钮点击位置的x坐标
  @State positionY: number = 0 // 按钮点击位置的y坐标
  @State state: boolean[] = [true, false] // 按钮状态数组
  @State index: number = 0 // 按钮状态索引

  build() {
    Column() {
      // 创建一个自定义样式的按钮
      Button('OK')
        .contentModifier(new MyButtonStyle(this.positionX, this.positionY, Color.Red))
        .onClick((event) => {
          console.info('change' + JSON.stringify(event))
          this.positionX = event.displayX // 更新按钮点击位置的x坐标
          this.positionY = event.displayY // 更新按钮点击位置的y坐标
        }).enabled(this.buttonEnabled) // 设置按钮的启用状态

      Row() {
        // 创建一个开关控件，用于控制按钮的启用或禁用状态
        Toggle({ type: ToggleType.Switch, isOn: true }).onChange((value: boolean) => {
          if (value) {
            this.buttonEnabled = true // 启用按钮
          } else {
            this.buttonEnabled = false // 禁用按钮
          }
        }).margin({ left: -80 }) // 设置开关控件的左边距
      }
    }.height('100%').width('100%').justifyContent(FlexAlign.Center) // 设置布局的高度、宽度和对齐方式
  }
}

示例：该组件通过 Flex 布局实现了一个展示多种类型按钮（如强调按钮、普通按钮、文本按钮）及其不同尺寸效果的界面。布局宽度占据整个屏幕，高度设为 400vp，内边距为左右 35vp、顶部 35vp。组件的垂直方向上被分为多个部分，每个部分包含一个标题和一组按钮。每个按钮组的按钮以水平布局方式排列，按钮之间的间距均匀分布，且对齐方式为居中对齐。
按钮的样式包括背景颜色、边框圆角（或半径）、宽度和高度等属性，支持不同的样式展示。按钮组之间通过 Flex 组件进行分隔。按钮的功能包括点击事件和状态效果，用户可以通过点击按钮触发相应操作，按钮也可以在启用或禁用状态下进行展示。
整个布局通过 Flex 布局保证按钮在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct ButtonExample {
  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Start, justifyContent: FlexAlign.SpaceBetween }) {
      // 创建一个文本组件，显示“Normal size button”，字体大小为9，颜色为0xCCCCCC
      Text('Normal size button').fontSize(9).fontColor(0xCCCCCC)
      // 创建一个水平布局的 Flex 组件，对齐方式为居中对齐，按钮之间的间距均匀分布
      Flex({ alignItems: ItemAlign.Center, justifyContent: FlexAlign.SpaceBetween }) {
        // 创建一个强调风格的按钮，显示文本“Emphasized”
        Button('Emphasized', { buttonStyle: ButtonStyleMode.EMPHASIZED });
        // 创建一个普通风格的按钮，显示文本“Normal”
        Button('Normal', { buttonStyle: ButtonStyleMode.NORMAL });
        // 创建一个文本风格的按钮，显示文本“Textual”
        Button('Textual', { buttonStyle: ButtonStyleMode.TEXTUAL });
      }

      // 创建一个文本组件，显示“Small size button”，字体大小为9，颜色为0xCCCCCC
      Text('Small size button').fontSize(9).fontColor(0xCCCCCC)
      // 创建一个水平布局的 Flex 组件，对齐方式为居中对齐，按钮之间的间距均匀分布
      Flex({ alignItems: ItemAlign.Center, justifyContent: FlexAlign.SpaceBetween }) {
        // 创建一个强调风格的小尺寸按钮，显示文本“Emphasized”
        Button('Emphasized', { controlSize: ControlSize.SMALL, buttonStyle: ButtonStyleMode.EMPHASIZED });
        // 创建一个普通风格的小尺寸按钮，显示文本“Normal”
        Button('Normal', { controlSize: ControlSize.SMALL, buttonStyle: ButtonStyleMode.NORMAL });
        // 创建一个文本风格的小尺寸按钮，显示文本“Textual”
        Button('Textual', { controlSize: ControlSize.SMALL, buttonStyle: ButtonStyleMode.TEXTUAL });
      }

      // 创建一个文本组件，显示“Small size button”，字体大小为9，颜色为0xCCCCCC
      Text('Small size button').fontSize(9).fontColor(0xCCCCCC)
      // 创建一个水平布局的 Flex 组件，对齐方式为居中对齐，按钮之间的间距均匀分布
      Flex({ alignItems: ItemAlign.Center, justifyContent: FlexAlign.SpaceBetween }) {
        // 创建一个强调风格的小尺寸按钮，显示文本“Emphasized”
        Button('Emphasized').controlSize(ControlSize.SMALL).buttonStyle(ButtonStyleMode.EMPHASIZED);
        // 创建一个普通风格的小尺寸按钮，显示文本“Normal”
        Button('Normal').controlSize(ControlSize.SMALL).buttonStyle(ButtonStyleMode.NORMAL);
        // 创建一个文本风格的小尺寸按钮，显示文本“Textual”
        Button('Textual').controlSize(ControlSize.SMALL).buttonStyle(ButtonStyleMode.TEXTUAL);
      }

    }.height(400).padding({ left: 35, right: 35, top: 35 })
  }
}

