.id('button2')
.onChange((isOn: boolean) => {
this.toggleChecked2 = isOn;
})

Toggle({ type: ToggleType.Button, isOn: this.toggleChecked3 }) {
Text('Button 3')
}
.id('button3')
.onChange((isOn: boolean) => {
this.toggleChecked3 = isOn;
})
}
.id('toggleButton')
}
```


