          .size({ width: 20, height: 20 }) // 设置复选框的大小为 20vp x 20vp
          .selectedColor('#007DFF') // 设置选中状态的颜色为蓝色
          .onChange((isOn: boolean) => { // 监听状态变化事件
            console.info('Component status:' + isOn) // 输出当前组件状态到控制台
          })
      }

      Text('type: Button').fontSize(12).fontColor(0xcccccc).width('90%') // 显示标题文本，字体大小为 12vp，颜色为灰色，宽度为 90%
      Flex({ justifyContent: FlexAlign.SpaceEvenly, alignItems: ItemAlign.Center }) { // 使用 Flex 布局，水平方向上均匀分布组件，垂直方向上居中对齐
        Toggle({ type: ToggleType.Button, isOn: false }) { // 创建一个按钮类型的切换组件，初始状态为关闭
          Text('status button').fontColor('#182431').fontSize(12) // 按钮内的文本，字体颜色为深色，字体大小为 12vp
        }.width(106) // 设置按钮的宽度为 106vp
        .selectedColor('rgba(0,125,255,0.20)') // 设置选中状态的颜色为半透明蓝色
        .onChange((isOn: boolean) => { // 监听状态变化事件
          console.info('Component status:' + isOn) // 输出当前组件状态到控制台
        })

        Toggle({ type: ToggleType.Button, isOn: true }) { // 创建一个按钮类型的切换组件，初始状态为开启
          Text('status button').fontColor('#182431').fontSize(12) // 按钮内的文本，字体颜色为深色，字体大小为 12vp
        }.width(106) // 设置按钮的宽度为 106vp
        .selectedColor('rgba(0,125,255,0.20)') // 设置选中状态的颜色为半透明蓝色
        .onChange((isOn: boolean) => { // 监听状态变化事件
          console.info('Component status:' + isOn) // 输出当前组件状态到控制台
        })
      }
    }.width('100%').padding(24) // 设置 Column 的宽度为 100%，内边距为 24vp
  }
}

// 自定义Toggle样式类，实现ContentModifier接口
class MySwitchStyle implements ContentModifier<ToggleConfiguration> {
  // 选中的颜色，默认为白色
  selectedColor: Color = Color.White;
  // 灯的标识符，默认为字符串
  lamp: string = 'string';

  // 构造函数，初始化selectedColor和lamp
  constructor(selectedColor: Color, lamp: string) {
    this.selectedColor = selectedColor;
    this.lamp = lamp;
  }

  // 应用内容的方法，返回一个WrappedBuilder
  applyContent(): WrappedBuilder<[ToggleConfiguration]> {
    return wrapBuilder(buildSwitch);
  }
}

// 构建Toggle内容的Builder函数
@Builder function buildSwitch(config: ToggleConfiguration) {
  // 创建一个Column组件，设置子组件之间的垂直间距为50
  Column({ space: 50 }) {
    // 创建一个Circle组件，设置宽度和高度均为150
    Circle({ width: 150, height: 150 })
      // 根据Toggle的状态设置填充颜色，当Toggle状态为true时，填充颜色为MySwitchStyle中的selectedColor，否则为默认的蓝色
      .fill(config.isOn ? (config.contentModifier as MySwitchStyle).selectedColor : Color.Blue)
    // 创建一个Row组件，用于水平排列按钮
    Row() {
      // 创建一个Button组件，显示“蓝”和lamp的值
      Button('蓝' + JSON.stringify((config.contentModifier as MySwitchStyle).lamp))
        // 设置点击事件，点击时触发Toggle状态的改变为false
        .onClick(() => {
          config.triggerChange(false);
        })
      // 创建一个Button组件，显示“黄”和lamp的值
      Button('黄' + JSON.stringify((config.contentModifier as MySwitchStyle).lamp))
        // 设置点击事件，点击时触发Toggle状态的改变为true
        .onClick(() => {
          config.triggerChange(true);
        })
    }
  }
}

// 入口组件
@Entry
@Component
struct Index {
  // 构建方法
  build() {
    // 创建一个Column组件，设置子组件之间的垂直间距为50
    Column({ space: 50 }) {
      // 创建一个Toggle组件，设置类型为Switch
      Toggle({ type: ToggleType.Switch })
        // 设置Toggle为启用状态
        .enabled(true)
        // 设置Toggle的内容修饰器为MySwitchStyle，初始颜色为黄色，lamp为“灯”
        .contentModifier(new MySwitchStyle(Color.Yellow, '灯'))
        // 设置Toggle状态改变时的回调函数，输出当前状态
        .onChange((isOn: boolean) => {
          console.info('Switch Log:' + isOn);
        })
    }
    // 设置Column组件的宽度和高度均为100%
    .height('100%').width('100%')
  }
}

