          .onChange((isOn: boolean) => { // 监听状态变化事件
            console.info('Component status:' + isOn) // 输出当前组件状态到控制台
          })

        Toggle({ type: ToggleType.Switch, isOn: true }) // 创建一个开关类型的切换组件，初始状态为开启
          .selectedColor('#007DFF') // 设置选中状态的颜色为蓝色
          .switchPointColor('#FFFFFF') // 设置开关滑块的颜色为白色
          .onChange((isOn: boolean) => { // 监听状态变化事件
            console.info('Component status:' + isOn) // 输出当前组件状态到控制台
          })
      }

      Text('type: Checkbox').fontSize(12).fontColor(0xcccccc).width('90%') // 显示标题文本，字体大小为 12vp，颜色为灰色，宽度为 90%
      Flex({ justifyContent: FlexAlign.SpaceEvenly, alignItems: ItemAlign.Center }) { // 使用 Flex 布局，水平方向上均匀分布组件，垂直方向上居中对齐
