# Marquee
接口描述：创建跑马灯组件。
接口参数：{'value': {"type":{"start":"boolean","step":"number","loop":"number","fromStart":"boolean","src":"string"},"required":true,"description":"配置跑马灯组件的参数。\n- start：控制跑马灯是否进入播放状态。\n- step：滚动动画文本滚动步长，当step大于Marquee的文本宽度时，取默认值。\n- loop：设置重复滚动的次数，小于等于零时无限循环。\n- fromStart：设置文本从头开始滚动或反向滚动。\n- src：需要滚动的文本。","default":{"step":6,"loop":-1,"fromStart":true}}}
设置父容器压缩尺寸分配给此属性所在组件的比例。当父容器为Column、Row时，需设置主轴方向的尺寸。
属性名称：flexShrink
属性参数：{'value': {"type":"number","required":true,"description":"设置父容器压缩尺寸分配给此属性所在组件的比例。","default":0}}
跑马灯组件属性更新后，跑马灯的滚动策略。(当跑马灯为播放状态，且文本内容宽度超过跑马灯组件宽度时，该属性生效。)
属性名称：marqueeUpdateStrategy
属性参数：{'value': {"type":"MarqueeUpdateStrategy","required":true,"description":"跑马灯组件属性更新后，跑马灯的滚动策略。","default":"MarqueeUpdateStrategy.DEFAULT"}}
示例：该组件通过 Flex 布局实现了一个包含跑马灯（Marquee）和按钮的界面。布局宽度占据整个屏幕，高度设为 100%，内边距为 0。组件的垂直方向上被分为多个部分，每个部分包含一个跑马灯和一个按钮。跑马灯和按钮以垂直布局方式排列，对齐方式为居中对齐。
跑马灯的样式包括宽度为 300vp，高度为 80vp，背景颜色为 #182431，字体颜色为 #FFFFFF，字体大小为 48，字体粗细为 700，底部边距为 40vp。跑马灯的功能包括开始、反弹和结束事件的回调函数，用户可以通过点击按钮触发跑马灯动画。
按钮的样式包括宽度为 120vp，高度为 40vp，背景颜色为 #007DFF，字体大小为 16，字体粗细为 500。按钮的功能包括点击事件，用户可以通过点击按钮启动跑马灯动画。
整个布局通过 Flex 布局保证跑马灯和按钮在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct MarqueeExample {
  @State start: boolean = false // 控制跑马灯动画是否开始的标志
  @State src: string = '' // 用于存储时间格式的字符串
  @State marqueeText: string = 'Running Marquee' // 跑马灯显示的文本
  private fromStart: boolean = true // 控制跑马灯动画是否从开始位置开始
  private step: number = 10 // 跑马灯动画的步长
  private loop: number = Number.POSITIVE_INFINITY // 跑马灯动画的循环次数，设置为无限循环
  controller: TextClockController = new TextClockController() // 控制时间显示的控制器

  // 将时间戳转换为时间格式的字符串
  convert2time(value: number): string{
    let date = new Date(Number(value+'000'));
    let hours = date.getHours().toString().padStart(2, '0');
    let minutes = date.getMinutes().toString().padStart(2, '0');
    let seconds = date.getSeconds().toString().padStart(2, '0');
    return hours+ ":" + minutes + ":" + seconds;
  }

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Marquee({
        start: this.start, // 控制跑马灯动画是否开始
        step: this.step, // 跑马灯动画的步长
        loop: this.loop, // 跑马灯动画的循环次数
        fromStart: this.fromStart, // 控制跑马灯动画是否从开始位置开始
        src: this.marqueeText + this.src // 跑马灯显示的文本内容
      })
        .marqueeUpdateStrategy(MarqueeUpdateStrategy.PRESERVE_POSITION) // 跑马灯更新策略，保持当前位置
        .width(300) // 跑马灯宽度
        .height(80) // 跑马灯高度
        .fontColor('#FFFFFF') // 跑马灯字体颜色
        .fontSize(48) // 跑马灯字体大小
        .fontWeight(700) // 跑马灯字体粗细
        .backgroundColor('#182431') // 跑马灯背景颜色
        .margin({ bottom: 40 }) // 跑马灯底部边距
        .onStart(() => {
          console.info('Marquee animation complete onStart') // 跑马灯动画开始时的回调函数
        })
        .onBounce(() => {
          console.info('Marquee animation complete onBounce') // 跑马灯动画反弹时的回调函数
        })
        .onFinish(() => {
          console.info('Marquee animation complete onFinish') // 跑马灯动画结束时的回调函数
        })
      Button('Start')
        .onClick(() => {
          this.start = true // 设置跑马灯动画开始标志
          this.controller.start() // 启动时间显示控制器
        })
        .width(120) // 按钮宽度
        .height(40) // 按钮高度
        .fontSize(16) // 按钮字体大小
        .fontWeight(500) // 按钮字体粗细
        .backgroundColor('#007DFF') // 按钮背景颜色
      TextClock({ timeZoneOffset: -8, controller: this.controller }) // 时间显示组件，时区偏移为-8小时
        .format('hms') // 时间格式为小时:分钟:秒
        .onDateChange((value: number) => {
          this.src = this.convert2time(value); // 时间变化时的回调函数，更新时间字符串
        })
        .margin(20) // 时间显示组件的边距
        .fontSize(30) // 时间显示组件的字体大小
    }
    .width('100%') // 布局宽度
    .height('100%') // 布局高度
  }
}

