事件参数：{'xOffset': {"type":"number","required":true,"description":"每帧滚动时水平方向的偏移量，Scroll中的内容向左滚动时偏移量为正，向右滚动时偏移量为负。单位vp。","default":null}, 'yOffset': {"type":"number","required":true,"description":"每帧滚动时竖直方向的偏移量，Scroll中的内容向上滚动时偏移量为正，向下滚动时偏移量为负。单位vp。","default":null}, 'scrollState': {"type":"ScrollState","required":true,"description":"当前滚动状态。","default":null}, 'scrollSource': {"type":"ScrollSource","required":true,"description":"当前滚动操作的来源。","default":null}}
